import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import GameCard from "../components/GameCard";
import { useGames } from "../hooks/useGames";
import { slugify } from "../utils/gameUtils";

export default function Home() {
  const { games, loading, CATEGORY_META } = useGames();

  const [searchTerm, setSearchTerm] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");

  useEffect(() => {
    document.title = "PokiPlay • Smart HTML5 Game Portal";
  }, []);

  // ✅ Hook #1
  const availableCategories = useMemo(() => {
    const grouped = games.reduce((acc, game) => {
      acc[game.category] = (acc[game.category] || 0) + 1;
      return acc;
    }, {});

    return [
      { category: "All", count: games.length },
      ...Object.entries(grouped)
        .sort((a, b) => b[1] - a[1])
        .map(([category, count]) => ({ category, count }))
    ];
  }, [games]);

  // ✅ Hook #2
  const filteredGames = useMemo(() => {
    const query = searchTerm.trim().toLowerCase();

    return games.filter((game) => {
      const matchQuery =
        !query || game.searchText.toLowerCase().includes(query);

      const matchCategory =
        activeCategory === "All" ||
        game.category === activeCategory;

      return matchQuery && matchCategory;
    });
  }, [games, searchTerm, activeCategory]);

  // ✅ Hook #3
  const categoryGroups = useMemo(() => {
    const groups = filteredGames.reduce((acc, game) => {
      acc[game.category] = acc[game.category] || [];
      acc[game.category].push(game);
      return acc;
    }, {});

    return Object.entries(groups)
      .sort((a, b) => b[1].length - a[1].length)
      .map(([category, items]) => ({
        category,
        items
      }));
  }, [filteredGames]);

  // ✅ AFTER ALL HOOKS
  if (loading) {
    return <h2 className="loading-text">Loading Games...</h2>;
  }

  return (
    <div className="home-page">
      <div className="home-hero">
        <div>
          <h2 className="page-title">
            🔥 Smart Game Library
          </h2>

          <p className="hero-copy">
            Browse automatic categories, search instantly,
            and discover the best HTML5 games with premium
            card animations.
          </p>
        </div>

        <div className="home-search-row">
          <input
            value={searchTerm}
            onChange={(e) =>
              setSearchTerm(e.target.value)
            }
            placeholder="Search by name, category, tags or description..."
            className="home-search-input"
          />
        </div>
      </div>

      <div className="category-toolbar">
        {availableCategories.map((item) => (
          <button
            key={item.category}
            className={`category-pill ${
              activeCategory === item.category
                ? "active"
                : ""
            }`}
            onClick={() =>
              setActiveCategory(item.category)
            }
          >
            {item.category}

            <span className="pill-count">
              {item.count}
            </span>
          </button>
        ))}
      </div>

      {categoryGroups.length === 0 ? (
        <p className="no-results">
          No games match that search.
          Try another keyword or category.
        </p>
      ) : (
        categoryGroups.map(({ category, items }) => {
          const meta =
            CATEGORY_META[category] ||
            CATEGORY_META.Other;

          return (
            <section
              id={slugify(category)}
              key={category}
              className="category-section"
            >
              <div className="category-header">
                <div>
                  <span
                    className="category-label"
                    style={{
                      background: `${meta.color}22`,
                      color: meta.color
                    }}
                  >
                    {meta.icon} {category}
                  </span>

                  <span className="category-count">
                    {items.length} games
                  </span>
                </div>

                <Link
                  className="category-view-more"
                  to={`/search?q=${encodeURIComponent(
                    searchTerm
                  )}&cat=${encodeURIComponent(
                    category
                  )}`}
                >
                  View all
                </Link>
              </div>

              <div className="section-carousel">
                {items.slice(0, 10).map((game) => (
                  <GameCard
                    key={game._id}
                    game={game}
                  />
                ))}
              </div>
            </section>
          );
        })
      )}
    </div>
  );
}
